"use strict";

// OneSend wrapper around the unmodified libcimbar v0.6.7c release worker.
// Lifecycle + a Worker-safe frame clock that respects setFPS.
self.window = self;

let running = false;
let frameCount = 0;
let loadGeneration = 0;
/**
 * Sole display pace. Upstream Send.nextFrame also gates on its own _interval;
 * if both are ~equal, floating timing skips/doubles frames and the barcode
 * looks like it is "shaking". We pace only here and force upstream interval
 * to 1ms so every polyfill tick advances exactly one fountain frame.
 */
let rafDelayMs = 250;
let lastUiPostAt = 0;

function postFrameIfNeeded() {
  // Throttle UI updates so React does not re-render every tick (causes shake).
  const now = self.performance.now();
  if (now - lastUiPostAt < 300) return;
  lastUiPostAt = now;
  frameCount += 1;
  self.postMessage({ type: "frame", count: frameCount });
}

/**
 * rAF polyfill. Previously always used 16ms and posted UI events every tick,
 * which made the page "shake" and fought setFPS. Pace with rafDelayMs instead.
 */
self.requestAnimationFrame = (callback) => {
  if (!running) return 0;
  return self.setTimeout(() => {
    if (!running) return;
    try {
      callback(self.performance.now());
      postFrameIfNeeded();
    } catch (error) {
      running = false;
      self.postMessage({
        type: "error",
        message: error instanceof Error ? error.message : String(error),
      });
    }
  }, Math.max(80, rafDelayMs));
};

self.cancelAnimationFrame = (handle) => self.clearTimeout(handle);

importScripts("/cimbar/onesend_cimbar_envelope.js");
importScripts("send-worker.2026-07-13T0523.js");

const upstreamOnMessage = self.onmessage;

function applySetFps(fps) {
  const value = Number(fps);
  if (Number.isFinite(value) && value > 0) {
    // Longer dwell helps phone cameras (rolling shutter + LCD). Cap at ~8 fps.
    const clamped = Math.min(8, Math.max(2, value));
    rafDelayMs = Math.max(120, Math.floor(1000 / clamped));
  }
}

async function loadFile(file) {
  const generation = ++loadGeneration;
  running = false;
  frameCount = 0;
  lastUiPostAt = 0;
  try {
    if (!file || typeof file.arrayBuffer !== "function") {
      throw new Error("没有选择有效文件。");
    }
    const input = new Uint8Array(await file.arrayBuffer());
    const envelope = self.OneSendCimbarEnvelope.encode({
      name: file.name || "cimbar-file.bin",
      mimeType: file.type || "application/octet-stream",
      bytes: input,
    });
    if (envelope.length > self.OneSendCimbarEnvelope.MAX_ENVELOPE_BYTES) {
      throw new Error("文件加上 CIMBAR envelope 后超过 33 MiB。");
    }
    if (generation !== loadGeneration) return;

    let wrapped;
    if (typeof File === "function") {
      wrapped = new File([envelope], file.name || "cimbar-file.bin", {
        type: "application/octet-stream",
      });
    } else {
      wrapped = new Blob([envelope], { type: "application/octet-stream" });
      Object.defineProperty(wrapped, "name", {
        value: file.name || "cimbar-file.bin",
      });
    }
    upstreamOnMessage({
      data: { fun: "importFile", args: [wrapped] },
    });
    running = true;
    upstreamOnMessage({ data: { fun: "nextFrame", args: [] } });
  } catch (error) {
    running = false;
    self.postMessage({
      type: "error",
      message: error instanceof Error ? error.message : String(error),
    });
  }
}

self.onmessage = (event) => {
  const data = event.data || {};

  if (data.type === "load") {
    void loadFile(data.file);
    return;
  }

  if (data.type === "start") {
    if (!running) {
      running = true;
      upstreamOnMessage({ data: { fun: "nextFrame", args: [] } });
    }
    return;
  }

  if (data.type === "stop") {
    loadGeneration += 1;
    running = false;
    self.postMessage({ type: "stopped" });
    return;
  }

  if (data.type === "dispose") {
    running = false;
    self.close();
    return;
  }

  if (data.fun === "setFPS" && Array.isArray(data.args) && data.args.length) {
    applySetFps(data.args[0]);
    // Upstream nextFrame gates on its own _interval. Keep that tiny so our
    // rafDelayMs is the only real clock (avoids double-gating / jitter).
    upstreamOnMessage({ data: { fun: "setFPS", args: [1000] } });
    return;
  }

  upstreamOnMessage(event);
};
